<?php
declare(strict_types=1);
function public_meter(array $m): array {
    $c=account_channel_public((int)$m['user_id']);
    return ['id'=>(int)$m['id'],'label'=>$m['label'],'school_code'=>$m['school_code'],'account'=>unseal($m['account_secret']),'college_note'=>$m['college_note'],'roomverify'=>$m['roomverify'],'business_type'=>$m['business_type'],'command'=>$m['command'],'enabled'=>(bool)$m['enabled'],'options'=>options($m),'channels'=>$c,'extra_channels'=>['webhook'=>$c['webhook'],'smtp'=>$c['smtp']],'templates'=>['daily'=>$c['daily']['templates'],'emergency'=>$c['emergency']['templates']],'rooms'=>state((int)$m['id'],'rooms',[])];
}
function daily_usage(array $intervals,int $days,float $now): array {$data=[];$today=strtotime(date('Y-m-d',(int)$now));for($i=$days-1;$i>=0;$i--){$date=date('Y-m-d',$today-$i*86400);$data[$date]=['date'=>$date,'energy'=>null,'covered_hours'=>0.];}foreach($intervals as $r){if(!(int)$r['usable']||$r['ts']<=$r['start']||$r['ts']>$now)continue;$duration=$r['ts']-$r['start'];for($t=max($r['start'],$today-($days-1)*86400);$t<$r['ts']&&$t<$today+86400;){$edge=min($r['ts'],strtotime(date('Y-m-d',(int)$t))+86400);$date=date('Y-m-d',(int)$t);if(isset($data[$date])){$data[$date]['energy']=($data[$date]['energy']??0)+$r['energy']*($edge-$t)/$duration;$data[$date]['covered_hours']+=($edge-$t)/3600;}$t=$edge;}}return array_values($data);}
function dashboard(array $m,int $days=14): array {
    $now=microtime(true);$id=(int)$m['id'];$o=options($m);[$day,$start,$end]=bounds($now,$o);$r=latest($m);$a=$r?json_decode($r['analysis'],true):null;$series=$r['series']??'';$intervals=sql('SELECT start,ts,hours,energy,usable,tag FROM ca_intervals WHERE meter_id=? AND revision=? AND series=? AND ts>=? AND ts<=? ORDER BY ts',[$id,$m['revision'],$series,strtotime($day)-($days-1)*86400,$now]);$history=sql('SELECT ts,balance,quality FROM ca_readings WHERE meter_id=? AND revision=? AND series=? AND ts>=? AND ts<=? ORDER BY ts',[$id,$m['revision'],$series,$now-$days*86400,$now]);
    $schedule=state($id,'schedule',[]);$next=($schedule['day']??'')===$day?($schedule['next']??$start):$start;if(state($id,'daily:'.$day)||$now>$end)$next=$start+86400;$reason=manual_reason($m,$now);$heartbeat=(float)setting('worker_heartbeat',0);$f=['available'=>false];
    if($a&&isset($a['forecast_run'])){$a=ts_project($a,$now,$o);$run=$a['forecast_run'];$age=max(0.,($now-$run['origin'])/3600);$active=!$a['provisional']&&$age<72&&$a['rate']>1e-6;$f=['available'=>$active,'remaining_hours'=>$run['zero_center']===null?null:max(0.,$run['zero_center']-$age),'empty_at'=>$run['zero_center']===null?null:$run['origin']+$run['zero_center']*3600,'reserve_at'=>$run['reserve_center']===null?null:$run['origin']+$run['reserve_center']*3600,'safe_at'=>$run['reserve_guard']===null?null:$run['origin']+$run['reserve_guard']*3600,'warning_at'=>$run['reserve_guard']===null?null:$run['origin']+max(0.,$run['reserve_guard']-$o['warning_hours'])*3600,'estimated_now_kwh'=>$a['estimated_now_kwh'],'lower_kwh'=>$a['balance_lower'],'data_age_hours'=>$a['data_age_hours'],'data_state'=>$a['data_state'],'mode'=>$run['mode'],'probabilities'=>null,'horizon_left_hours'=>max(0.,72-$age),'beyond_horizon'=>$run['zero_center']===null,'action_by'=>$run['zero_guard']===null?null:$run['origin']+max(0.,$run['zero_guard']-2.)*3600,'origin'=>$run['origin'],'meter_ts'=>$run['meter_ts'],'points'=>$run['points']];}

    $reading=$r?['ts'=>(float)$r['ts'],'balance'=>(float)$r['balance'],'room'=>$r['room'],'quality'=>$r['quality'],'balance_raw'=>$r['balance_raw']??null,'meter_ts'=>$r['meter_ts']??null]:null;
    return ['now'=>$now,'reading'=>$reading,'analysis'=>$a,'forecast'=>$f,'daily'=>daily_usage($intervals,$days,$now),'intervals'=>$intervals,'history'=>$history,'risk'=>state($id,'risk',['level'=>'normal']),'next_query'=>(int)$m['enabled']?$next:null,'schedule'=>$schedule,'count'=>quota($id,$day),'cap'=>$o['max_queries'],'manual_reason'=>$reason,'heartbeat'=>$heartbeat,'last_tick'=>(float)$m['last_tick'],'config'=>$o,'events'=>sql('SELECT ts,kind,details FROM ca_events WHERE meter_id=? ORDER BY id DESC LIMIT 60',[$id]),'attempts'=>sql('SELECT ts,kind,state,error FROM ca_attempts WHERE meter_id=? ORDER BY id DESC LIMIT 30',[$id]),'notifications'=>sql('SELECT channel AS kind,created,state,details FROM ca_outbox WHERE meter_id=? ORDER BY id DESC LIMIT 30',[$id]),'forecast_audit'=>['runs'=>(int)one('SELECT COUNT(*) n FROM ca_forecast_runs WHERE meter_id=? AND revision=?',[$id,$m['revision']])['n'],'evaluations'=>sql('SELECT e.status,COUNT(*) n,AVG(ABS(e.error_kwh)) mae FROM ca_forecast_evaluations e JOIN ca_forecast_runs f ON f.id=e.forecast_id WHERE f.meter_id=? AND f.revision=? GROUP BY e.status',[$id,$m['revision']])],'job'=>one('SELECT id,created,state,message FROM ca_jobs WHERE meter_id=? ORDER BY id DESC LIMIT 1',[$id])];
}
function save_meter(array $body,array $u): int {
    return transaction(function()use($body,$u){$id=(int)($body['id']??0);$old=$id?owner_meter($id,$u,true):null;one('SELECT id FROM ca_users WHERE id=? FOR UPDATE',[$u['id']]);if(!$old&&$u['role']!=='admin'&&(int)one('SELECT COUNT(*) n FROM ca_meters WHERE user_id=?',[$u['id']])['n']>=(int)setting('max_meters_per_user',5))throw new AppError('已达到此账户的监控项目上限');
        $label=trim((string)($body['label']??''));$school=trim((string)($body['school_code']??''));$account=trim((string)($body['account']??''));$room=trim((string)($body['roomverify']??''));$college=trim((string)($body['college_note']??''));$command=trim((string)($body['command']??'JBSWaterElecService'));$business=(string)($body['business_type']??'0');
        if($label===''||mb_strlen($label)>100||!preg_match('/^[A-Za-z0-9_-]{1,40}$/D',$school)||!preg_match('/^[A-Za-z0-9_-]{1,80}$/D',$account)||mb_strlen($room)>150||mb_strlen($college)>100||!preg_match('/^[A-Za-z0-9_]{1,64}$/D',$command)||$business!=='0')throw new AppError('查询字段无效；本版监控电量，业务类型为0');
        $o=default_options();$input=$body['options']??[];foreach(['window_start','window_end'] as $k){$v=(string)($input[$k]??$o[$k]);if(!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$v))throw new AppError('查询时段须为 HH:MM');$o[$k]=$v;}if($o['window_start']>=$o['window_end'])throw new AppError('查询时段必须在同一天内');
        foreach(['max_queries','min_gap_minutes'] as $k)$o[$k]=(int)($input[$k]??$o[$k]);if($o['max_queries']<3||$o['max_queries']>8||$o['min_gap_minutes']<60||$o['min_gap_minutes']>240||strtotime('2000-01-01 '.$o['window_end'])-strtotime('2000-01-01 '.$o['window_start'])<2*$o['min_gap_minutes']*60)throw new AppError('每日上限3～8次，最短间隔60～240分钟，窗口至少容纳三次查询');
        foreach(['warning_kwh','critical_kwh','clear_kwh','reserve_kwh'] as $k){$v=$input[$k]??$o[$k];if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<=0||(float)$v>10000)throw new AppError('电量阈值须为有效正数');decimal_kwh((string)$v);$o[$k]=(float)$v;}if(!($o['critical_kwh']<$o['warning_kwh']&&$o['warning_kwh']<$o['clear_kwh'])||$o['reserve_kwh']>$o['warning_kwh'])throw new AppError('阈值须满足：紧急 < 预警 < 恢复，预留不得高于预警');
        $enabled=(bool)($body['enabled']??true);$changed=$old&&($school!==$old['school_code']||$account!==unseal($old['account_secret'])||$room!==$old['roomverify']||$command!==$old['command']||$business!==$old['business_type']);$revision=$old?(int)$old['revision']+(int)$changed:1;
        if($old)sql('UPDATE ca_meters SET label=?,school_code=?,account_secret=?,college_note=?,roomverify=?,business_type=?,command=?,enabled=?,revision=?,settings=? WHERE id=?',[$label,$school,seal($account),$college,$room,$business,$command,(int)$enabled,$revision,json_value($o),$id]);else{sql('INSERT INTO ca_meters(user_id,label,school_code,account_secret,college_note,roomverify,business_type,command,enabled,revision,settings,created) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$u['id'],$label,$school,seal($account),$college,$room,$business,$command,(int)$enabled,$revision,json_value($o),microtime(true)]);$id=(int)db()->lastInsertId();}
        if($changed){set_state($id,'risk',['level'=>'normal']);if($school!==$old['school_code']||$account!==unseal($old['account_secret'])||$command!==$old['command']||$business!==$old['business_type'])set_state($id,'rooms',[]);event($id,microtime(true),'config_changed',['revision'=>$revision]);}
        if($old&&(json_value($o)!==json_value(options($old))||$changed)){sql("UPDATE ca_jobs SET state='blocked',message='设置已改变，请重新提交' WHERE meter_id=? AND state='queued'",[$id]);sql("DELETE FROM ca_state WHERE meter_id=? AND `name`='schedule'",[$id]);sql('UPDATE ca_meters SET next_query=0 WHERE id=?',[$id]);}
        if(!$enabled||$changed){sql("UPDATE ca_outbox SET state='cancelled',details='监控暂停或查询配置已改变' WHERE meter_id=? AND state='queued'",[$id]);sql("UPDATE ca_jobs SET state='blocked',message='监控暂停或查询配置已改变' WHERE meter_id=? AND state='queued'",[$id]);}return $id;
    });
}
